+class BidiReactor final : public grpc::ServerBidiReactor<OutputRequest, OutputResponse> {
+ public:
+  BidiReactor() { StartRead(&request_); }
+  void OnReadDone(bool ok) override {
+    if (!ok) { Finish(grpc::Status::OK); return; }
+    index_ = 0;
+    Next();
